def init_agent():
    return {'known': jnp.full((9,), -1, jnp.int32),
            'positions': jnp.zeros((9, 2), jnp.int32),
            'partner_move': jnp.full((), -1, jnp.int32),
            'evidence': jnp.zeros((280,), jnp.float32),
            'predicted': jnp.full((9, 3), 1 / 3, jnp.float32),
            'trust': jnp.asarray(1.0, jnp.float32)}


def belief(obs, known, evidence):
    ASSIGNMENTS = jnp.asarray(ASSIGNMENT_DATA, jnp.int32)
    ONE_HOT = jax.nn.one_hot(ASSIGNMENTS, 3).reshape(1680, 27)
    SAME = (ASSIGNMENTS[:, :, None] == ASSIGNMENTS[:, None, :]).reshape(1680, 81).astype(jnp.float32)
    CARDS = jnp.arange(9)
    features = obs.node_features
    hint_match = jnp.all(obs.positions[None, :, :] == features[9:, None, 6:8], axis=-1)
    hint_match = hint_match & (features[9:, 8, None] > 0)
    hint_sets = features[9:, 3:6].astype(jnp.float32)
    likelihood = jnp.prod(jnp.where(hint_match[:, :, None], 0.02 + 0.98 * hint_sets[:, None, :], 1.0), axis=0)
    log_likelihood = jnp.log(likelihood)
    scores = jnp.sum(log_likelihood[CARDS[None, :], ASSIGNMENTS], axis=1)
    scores += evidence[jnp.asarray(PARTITION_INDEX, jnp.int32)]
    valid = jnp.all((known[None, :] < 0) | (ASSIGNMENTS == known[None, :]), axis=1)
    weights = jax.nn.softmax(jnp.where(valid, scores, -1e9))
    marginal = (weights @ ONE_HOT).reshape(9, 3)
    pair = (weights @ SAME).reshape(9, 9) * (1 - jnp.eye(9))
    return weights, marginal, pair


def movement_options(positions, locked):
    cards = jnp.arange(9)
    move_card = jnp.repeat(cards, 81)
    dest = jnp.tile(jnp.stack((jnp.arange(81) // 9, jnp.arange(81) % 9), -1), (9, 1))
    distance = jnp.sum(jnp.abs(positions[:, None, :] - positions[None, :, :]), axis=-1)
    adjacency = distance == 1
    new_distance = jnp.sum(jnp.abs(dest[:, None, :] - positions[None, :, :]), axis=-1)
    new_adj = (new_distance == 1) & (cards[None, :] != move_card[:, None])
    # Connectivity of the eight remaining cards, separately for each removal.
    remaining = cards[None, :] != cards[:, None]
    reach = (adjacency[None, :, :] | jnp.eye(9, dtype=jnp.bool_)[None, :, :]) & remaining[:, :, None] & remaining[:, None, :]
    def closure(k, reach):
        return reach | (reach[:, :, k, None] & reach[:, None, k, :])
    reach = jax.lax.fori_loop(0, 9, closure, reach)
    covered = jnp.any(new_adj[:, :, None] & reach[move_card, :, :], axis=1)
    connected = jnp.all(covered | (cards[None, :] == move_card[:, None]), axis=-1)
    legal = connected & (~jnp.any(new_distance == 0, axis=-1)) & (~locked[move_card])
    edge_delta = new_adj.astype(jnp.float32) - adjacency[move_card, :].astype(jnp.float32)
    distance_delta = new_distance - distance[move_card, :]
    return legal, edge_delta - 0.06 * distance_delta


def observation_value(weights, marginal, move_legal, move_features):
    assignments = jnp.asarray(ASSIGNMENT_DATA, jnp.int32)
    one_hot = jax.nn.one_hot(assignments, 3).reshape(1680, 27)
    same = (assignments[:, :, None] == assignments[:, None, :]).reshape(1680, 81).astype(jnp.float32)
    conditional = ((weights[:, None] * one_hot).T @ same) / jnp.maximum(marginal.reshape(27, 1), 1e-8)
    conditional = conditional.reshape(27, 9, 9) * (1 - jnp.eye(9))[None, :, :]
    move_card = jnp.repeat(jnp.arange(9), 81)
    values = jnp.sum(conditional[:, move_card, :] * move_features[None, :, :], axis=-1)
    best = jnp.max(jnp.where(move_legal[None, :], values, -1e6), axis=-1).reshape(9, 3)
    return jnp.sum(marginal * best, axis=-1)


def partner_likelihood(previous, positions, locked, seen):
    assignments = jnp.asarray(PARTITION_DATA, jnp.int32)
    one_hot = jax.nn.one_hot(assignments, 3)
    same = assignments[:, :, None] == assignments[:, None, :]
    remaining = 3.0 - jnp.sum(one_hot * seen[None, :, None], axis=1)
    unknown_count = 9.0 - jnp.sum(seen)
    known_unknown = jnp.take_along_axis(remaining, assignments, axis=1) / jnp.maximum(unknown_count, 1.0)
    unknown_unknown = jnp.sum(remaining * (remaining - 1), axis=1) / jnp.maximum(unknown_count * (unknown_count - 1), 1.0)
    pair = jnp.where(seen[None, :, None] > 0,
                     jnp.where(seen[None, None, :] > 0, same.astype(jnp.float32), known_unknown[:, :, None]),
                     jnp.where(seen[None, None, :] > 0, known_unknown[:, None, :], unknown_unknown[:, None, None]))
    pair *= (1 - jnp.eye(9))[None, :, :]
    legal, features = movement_options(previous, locked)
    values = jnp.einsum('sij,iaj->sia', pair, features.reshape(9, 81, 9)).reshape(280, 729)
    moved = jnp.argmax(jnp.any(previous != positions, axis=-1))
    chosen = moved * 81 + positions[moved, 0] * 9 + positions[moved, 1]
    log_policy = jax.nn.log_softmax(jnp.where(legal[None, :], 5.0 * values, -1e6), axis=-1)[:, chosen]
    # Partners may use planning or another reasonable movement objective.
    log_likelihood = jnp.logaddexp(jnp.log(0.80) + log_policy,
                                  jnp.log(0.20) - jnp.log(jnp.maximum(jnp.sum(legal), 1)))
    return log_likelihood - jnp.max(log_likelihood)


def flexible_move(positions, locked, pair, scores, legal):
    masked = jnp.where(legal, scores, -1e9)
    per_card = jnp.argmax(masked.reshape(9, 81), axis=-1) + jnp.arange(9) * 81
    _, top = jax.lax.top_k(masked, 7)
    first = jnp.concatenate((per_card, top))
    moved_card = first // 81
    cell = first % 81
    destinations = jnp.stack((cell // 9, cell % 9), axis=-1)
    boards = jnp.broadcast_to(positions, (16, 9, 2)).at[jnp.arange(16), moved_card, :].set(destinations)
    next_legal, next_features = jax.vmap(movement_options, in_axes=(0, None))(boards, locked)
    incident = pair[jnp.repeat(jnp.arange(9), 81), :]
    next_values = jnp.sum(next_features * incident[None, :, :], axis=-1)
    next_gain = jnp.maximum(jnp.max(jnp.where(next_legal, next_values, -1e9), axis=-1), 0)
    # Favor future options among moves with comparable immediate quality.
    eligible = legal[first] & (scores[first] >= jnp.max(masked) - 0.12)
    values = jnp.where(eligible, scores[first] + 0.35 * next_gain, -1e9)
    best = jnp.argmax(values)
    return first[best], next_gain[best]


def agent_act(obs, reset, memory, rng):
    memory = jax.tree.map(lambda a, b: jnp.where(reset, a, b), init_agent(), memory)
    ASSIGNMENTS = jnp.asarray(ASSIGNMENT_DATA, jnp.int32)
    SAME = (ASSIGNMENTS[:, :, None] == ASSIGNMENTS[:, None, :]).reshape(1680, 81).astype(jnp.float32)
    CARDS = jnp.arange(9)
    MOVE_CARD = jnp.repeat(CARDS, 81)
    MOVE_POS = jnp.tile(jnp.stack((jnp.arange(81) // 9, jnp.arange(81) % 9), -1), (9, 1))
    nf = obs.node_features
    active = nf[0, 10] > 0
    phase = nf[0, 11].astype(jnp.int32)
    visible = jnp.sum(nf[:9, :3], axis=-1) > 0
    known = jnp.where(visible, jnp.argmax(nf[:9, :3], axis=-1).astype(jnp.int32), memory['known'])
    moved = jnp.any(obs.positions != memory['positions'], axis=-1)
    partner_move = jnp.where((~active) & (phase == 3) & jnp.any(moved) & (~reset), jnp.argmax(moved), memory['partner_move']).astype(jnp.int32)
    singleton_hint = (jnp.sum(nf[9:, 3:6], axis=-1) == 1) & (nf[9:, 8] > 0)
    hint_target = jnp.all(obs.positions[None, :, :] == nf[9:, None, 6:8], axis=-1)
    public_known = jnp.any(singleton_hint[:, None] & hint_target, axis=0)
    partner_seen = ((nf[:9, 9] > 0) | public_known).astype(jnp.float32)
    evidence_delta = partner_likelihood(memory['positions'], obs.positions, nf[:9, 8] > 0, partner_seen)
    newly_observed = visible & (memory['known'] < 0)
    old_counts = jnp.sum(jax.nn.one_hot(jnp.maximum(memory['known'], 0), 3) * (memory['known'] >= 0)[:, None], axis=0)
    count_prior = (3 - old_counts) / jnp.maximum(jnp.sum(memory['known'] < 0), 1)
    predicted_actual = jnp.sum(memory['predicted'] * nf[:9, :3], axis=-1)
    count_actual = jnp.sum(count_prior[None, :] * nf[:9, :3], axis=-1)
    surprise = jnp.any(newly_observed & (predicted_actual < 0.15) & (predicted_actual < 0.33 * count_actual))
    trust = jnp.where(surprise, jnp.maximum(0.25, 0.7 * memory['trust']), jnp.minimum(1.0, memory['trust'] + 0.01 * jnp.sum(newly_observed)))
    evidence = memory['evidence'] * jnp.where(surprise, 0.5, 1.0) + trust * jnp.where((~active) & (phase == 3) & jnp.any(moved) & (~reset), evidence_delta, 0.0)
    evidence = jnp.maximum(evidence - jnp.max(evidence), -8.0)
    weights, marginal, pair = belief(obs, known, evidence)
    distances = jnp.sum(jnp.abs(obs.positions[:, None, :] - obs.positions[None, :, :]), axis=-1)
    adj = (distances == 1).astype(jnp.float32)
    assignment_edges = (SAME @ adj.reshape(81)) * 0.5
    solved = jnp.sum(weights * (assignment_edges > 5.99))
    entropy = -jnp.sum(marginal * jnp.log(jnp.maximum(marginal, 1e-9)), axis=-1)
    known_neighbors = adj @ (known >= 0).astype(jnp.float32)
    move_legal, move_features = movement_options(obs.positions, nf[:9, 8] > 0)
    voi = observation_value(weights, marginal, move_legal, move_features)
    inspect_scores = voi + 0.10 * entropy * (1 + 0.15 * known_neighbors - 0.35 * nf[:9, 9] + 0.15 * (CARDS == partner_move))
    inspect_scores -= 0.001 * CARDS
    inspect = 1 + jnp.argmax(jnp.where(obs.legal_actions[1:10], inspect_scores, -1e9))
    placed = nf[9:, 8] > 0
    revealed = jnp.sum(nf[9:, 3:6], axis=-1) > 0
    n_unrevealed = jnp.sum(~revealed)
    n_ready = jnp.sum(revealed & (~placed))
    n_placed = jnp.sum(placed)
    target_card = jnp.argmax(hint_target, axis=-1)
    assigned_hint_colors = ASSIGNMENTS[:, target_card]
    hint_correct = jnp.take_along_axis(nf[9:, 3:6][None, :, :], assigned_hint_colors[:, :, None], axis=-1)[:, :, 0]
    terminal_values = 5 * n_unrevealed + 2 * n_ready + jnp.sum(jnp.where(placed[None, :], 2 * hint_correct - 1, 0), axis=-1)
    stop_value = jnp.sum(weights * (assignment_edges > 5.99) * terminal_values)
    maximum_current = 5 * n_unrevealed + 2 * n_ready + n_placed
    continuation_upper_bound = maximum_current - jnp.where(n_ready > 0, 1, 3)
    should_stop = (solved > 0.80) | (stop_value > continuation_upper_bound + 1e-4)
    inspect = jnp.where((phase == 0) & should_stop, 1067, inspect)

    new_distances = jnp.sum(jnp.abs(MOVE_POS[:, None, :] - obs.positions[None, :, :]), axis=-1)
    new_adj = (new_distances == 1).astype(jnp.float32)
    incident = pair[MOVE_CARD, :]
    delta = jnp.sum(incident * (new_adj - adj[MOVE_CARD, :]), axis=-1)
    dist_delta = jnp.sum(incident * (new_distances - distances[MOVE_CARD, :]), axis=-1)
    compact = jnp.sum((new_adj - adj[MOVE_CARD, :]) * (CARDS[None, :] != MOVE_CARD[:, None]), axis=-1)
    partitions = jnp.asarray(PARTITION_DATA, jnp.int32)
    partition_same = (partitions[:, :, None] == partitions[:, None, :]).astype(jnp.float32) * (1 - jnp.eye(9))[None, :, :]
    partition_weights = jnp.zeros((280,), jnp.float32).at[jnp.asarray(PARTITION_INDEX, jnp.int32)].add(weights)
    partition_edges = (partition_same.reshape(280, 81) @ adj.reshape(81)) * 0.5
    edge_change = new_adj - adj[MOVE_CARD, :]
    partition_change = jnp.einsum('sij,iaj->sia', partition_same, edge_change.reshape(9, 81, 9)).reshape(280, 729)
    finish_probability = partition_weights @ ((partition_edges[:, None] + partition_change) > 5.99).astype(jnp.float32)
    unrevealed = jnp.sum(jnp.sum(nf[9:, 3:6], axis=-1) == 0)
    hint_actions_left = 4 + unrevealed - jnp.sum(nf[9:, 8])
    shared_incident = incident * partner_seen[MOVE_CARD, None] * partner_seen[None, :]
    legibility = jnp.sum(shared_incident * (new_adj - adj[MOVE_CARD, :]), axis=-1)
    base_move_scores = delta - 0.06 * dist_delta + 0.003 * compact + 0.10 * legibility
    move_scores = jnp.where(hint_actions_left == 1, 10 * finish_probability + 0.05 * base_move_scores,
                            base_move_scores + finish_probability)
    first, next_gain = flexible_move(obs.positions, nf[:9, 8] > 0, pair, move_scores, obs.legal_actions[10:739])
    greedy = jnp.argmax(jnp.where(obs.legal_actions[10:739], move_scores, -1e9))
    move = 10 + jnp.where(hint_actions_left > 1, first, greedy)

    # Preserve flexibility and reward by revealing before placing.
    reveal = 739 + jnp.argmax(obs.legal_actions[739:743])
    sets = nf[9:, 3:6].astype(jnp.float32)
    correct = sets @ marginal.T
    stability = jnp.sum(pair * adj, axis=-1)
    # A well-connected, known card is the least costly card to lock.
    information = (3 - jnp.sum(sets, axis=-1))[:, None] * (1 - partner_seen[None, :])
    lock_scores = 8 * correct + stability[None, :] + 0.1 * (known >= 0)[None, :] + 0.20 * information
    card_at_cell = jnp.all(MOVE_POS[:81, None, :] == obs.positions[None, :, :], axis=-1)
    placement_scores = lock_scores @ card_at_cell.T.astype(jnp.float32)
    place = 743 + jnp.argmax(jnp.where(obs.legal_actions[743:1067], placement_scores.reshape(324), -1e9))
    singleton = jnp.sum(sets, axis=-1) == 1
    eligible_early = (correct > 0.99) & (known >= 0)[None, :] & (stability[None, :] > 0.95)
    eligible_cells = (eligible_early.astype(jnp.float32) @ card_at_cell.T.astype(jnp.float32)) > 0
    early_mask = obs.legal_actions[743:1067] & eligible_cells.reshape(324)
    early_place = 743 + jnp.argmax(jnp.where(early_mask, placement_scores.reshape(324), -1e9))
    hint = jnp.where(jnp.any(early_mask), early_place,
                     jnp.where(jnp.any(obs.legal_actions[739:743]), reveal, place))
    action = jnp.where(phase < 2, inspect, jnp.where(phase == 2, move, hint))
    action = jnp.where(active, action, 0).astype(jnp.int32)
    # A legal fallback also covers any unforeseen observation-mask edge case.
    action = jnp.where(obs.legal_actions[action], action, jnp.argmax(obs.legal_actions)).astype(jnp.int32)
    next_memory = {'known': known, 'positions': obs.positions, 'partner_move': partner_move, 'evidence': evidence, 'predicted': marginal, 'trust': trust}
    trace = {'known': known, 'positions': obs.positions, 'hint_sets': nf[9:, 3:6], 'locks': nf[:9, 8], 'model_trust': trust, 'model_surprise': surprise, 'marginal': marginal, 'solved_probability': solved,
             'expected_edges': jnp.sum(pair * adj) / 2, 'observation_value': voi,
             'next_move_gain': next_gain, 'stop_value': stop_value,
             'continuation_upper_bound': continuation_upper_bound,
             'best_finish_probability': jnp.max(jnp.where(move_legal, finish_probability, 0)),
             'move_mask_errors': jnp.where(active & (phase == 2), jnp.sum(move_legal != obs.legal_actions[10:739]), 0), 'partner_move': partner_move, 'evidence': evidence}
    return action, next_memory, trace
